	('ab283896-9123-4b1b-b710-4a56f77f7962', '8ef5fa21-9801-4913-845e-98c4e1ac2ced', 'Calendar', 'Day calculation', 'If today is Thursday, what day of the week will it be after 45 days?', '45 mod 7 = 3; Thursday + 3 day(s) = Sunday.', 'MEDIUM', 1, 0.25, 'PUBLISHED', '2026-11-04 06:09:32.698', '2026-11-04 06:09:32.698', NULL, NULL, NULL, NULL, NULL, NULL, 'MCQ'),
	('d02893f7-4e2c-448e-9fd0-9275140db8f4', '8ef5fa21-9801-4913-845e-98c4e1ac2ced', 'Calendar', 'Day calculation', 'If today is Tuesday, what day of the week will it be after 100 days?', '100 mod 7 = 2; Tuesday + 2 day(s) = Thursday.', 'MEDIUM', 1, 0.25, 'PUBLISHED', '2026-11-04 06:09:32.698', '2026-11-04 06:09:32.698', NULL, NULL, NULL, NULL, NULL, NULL, 'MCQ'),
	('6efc7eb9-f459-4baf-83db-3bda38935e39', '8ef5fa21-9801-4913-845e-98c4e1ac2ced', 'Calendar', 'Day calculation', 'If today is Friday, what day of the week will it be after 45 days?', '45 mod 7 = 3; Friday + 3 day(s) = Monday.', 'MEDIUM', 1, 0.25, 'PUBLISHED', '2026-11-04 06:09:32.698', '2026-11-04 06:09:32.698', NULL, NULL, NULL, NULL, NULL, NULL, 'MCQ'),
	('b7fdecfc-1da8-466b-8f89-102b81b20950', '8ef5fa21-9801-4913-845e-98c4e1ac2ced', 'Calendar', 'Day calculation', 'If today is Saturday, what day of the week will it be after 60 days?', '60 mod 7 = 4; Saturday + 4 day(s) = Wednesday.', 'MEDIUM', 1, 0.25, 'PUBLISHED', '2026-11-04 06:09:32.698', '2026-11-04 06:09:32.698', NULL, NULL, NULL, NULL, NULL, NULL, 'MCQ'),
	('8b849972-9cba-4650-ba04-c96c06174869', '8ef5fa21-9801-4913-845e-98c4e1ac2ced', 'Calendar', 'Day calculation', 'If today is Wednesday, what day of the week will it be after 30 days?', '30 mod 7 = 2; Wednesday + 2 day(s) = Friday.', 'MEDIUM', 1, 0.25, 'PUBLISHED', '2026-11-04 06:09:32.698', '2026-11-04 06:09:32.698', NULL, NULL, NULL, NULL, NULL, NULL, 'MCQ'),
	('fe9925de-4e96-402e-a2d7-6485eda59531', '8ef5fa21-9801-4913-845e-98c4e1ac2ced', 'Calendar', 'Day calculation', 'If today is Wednesday, what day of the week will it be after 60 days?', '60 mod 7 = 4; Wednesday + 4 day(s) = Sunday.', 'MEDIUM', 1, 0.25, 'PUBLISHED', '2026-11-04 06:09:32.698', '2026-11-04 06:09:32.698', NULL, NULL, NULL, NULL, NULL, NULL, 'MCQ'),
	('da719fcf-c52e-4f4c-849d-fb6fd06572b7', '8ef5fa21-9801-4913-845e-98c4e1ac2ced', 'Clocks', 'Angle between hands', 'What is the angle between the hour hand and the minute hand at 7:00?', 'Each hour is 30°. At 7:00 the angle is 7 × 30 = 210° (smaller angle 150°).', 'EASY', 1, 0.25, 'PUBLISHED', '2026-11-04 06:09:32.698', '2026-11-04 06:09:32.698', NULL, NULL, NULL, NULL, NULL, NULL, 'MCQ'),
	('9eddf853-27bc-40b4-a324-5024b0bb0fe6', '8ef5fa21-9801-4913-845e-98c4e1ac2ced', 'Clocks', 'Angle between hands', 'What is the angle between the hour hand and the minute hand at 6:00?', 'Each hour is 30°. At 6:00 the angle is 6 × 30 = 180° (smaller angle 180°).', 'EASY', 1, 0.25, 'PUBLISHED', '2026-11-04 06:09:32.698', '2026-11-04 06:09:32.698', NULL, NULL, NULL, NULL, NULL, NULL, 'MCQ'),
