INSERT INTO public.questions VALUES
	('7b54dac7-d3d7-400d-a91b-23164eba35b1', '3248dc48-ece6-47ac-9c1e-7f5742335d61', 'Programming', 'Bitwise operators', 'What is the value of 40 ^ 30 in C/Java?', 'Applying ^ bitwise on 101000 and 11110 gives 110110 = 54.', 'MEDIUM', 1, 0.25, 'PUBLISHED', '2026-11-04 06:09:32.698', '2026-11-04 06:09:32.698', NULL, NULL, NULL, NULL, NULL, NULL, 'MCQ'),
	('8bb7d5c9-66b6-40cc-88dd-83c0994c2f6c', '3248dc48-ece6-47ac-9c1e-7f5742335d61', 'Programming', 'Bitwise operators', 'What is the value of 60 ^ 21 in C/Java?', 'Applying ^ bitwise on 111100 and 10101 gives 101001 = 41.', 'MEDIUM', 1, 0.25, 'PUBLISHED', '2026-11-04 06:09:32.698', '2026-11-04 06:09:32.698', NULL, NULL, NULL, NULL, NULL, NULL, 'MCQ'),
