INSERT INTO public.questions VALUES
	('0d27563e-324e-434f-b22c-005ffaf99de1', '087a6a1a-cc66-41c6-b078-397d652b5f14', 'Permutation & Combination', 'Repeated letters', 'In how many distinct ways can the letters of the word "MISSISSIPPI" be arranged?', '11! divided by the factorial of each repeated letter''s count = 34650.', 'HARD', 1, 0.25, 'PUBLISHED', '2026-11-04 06:09:33.588', '2026-11-04 06:09:33.588', NULL, NULL, NULL, NULL, NULL, NULL, 'MCQ'),
	('b60d4b5e-ec3a-45a9-ab4d-dc21e2a72456', '087a6a1a-cc66-41c6-b078-397d652b5f14', 'Permutation & Combination', 'Repeated letters', 'In how many distinct ways can the letters of the word "LEVEL" be arranged?', '5! divided by the factorial of each repeated letter''s count = 30.', 'HARD', 1, 0.25, 'PUBLISHED', '2026-11-04 06:09:33.588', '2026-11-04 06:09:33.588', NULL, NULL, NULL, NULL, NULL, NULL, 'MCQ'),
