	('e4409554-5f0e-4fa8-a075-d54511292d4c', '8ef5fa21-9801-4913-845e-98c4e1ac2ced', 'Number Series', 'Cubes', 'Complete the series: 68, 130, 222, 350, 520, ?', 'Terms are n³ + n for n = 4, 5, …; next n = 9 gives 738.', 'HARD', 1, 0.25, 'PUBLISHED', '2026-11-04 06:09:33.588', '2026-11-04 06:09:33.588', NULL, NULL, NULL, NULL, NULL, NULL, 'MCQ'),
	('b1f56350-ebca-4cf2-b05a-f42e742736bd', '8ef5fa21-9801-4913-845e-98c4e1ac2ced', 'Number Series', 'Cubes', 'Complete the series: 10, 30, 68, 130, 222, ?', 'Terms are n³ + n for n = 2, 3, …; next n = 7 gives 350.', 'HARD', 1, 0.25, 'PUBLISHED', '2026-11-04 06:09:33.588', '2026-11-04 06:09:33.588', NULL, NULL, NULL, NULL, NULL, NULL, 'MCQ'),
	('7c0c0e96-03eb-4411-98a2-7c3e09e645e4', '8ef5fa21-9801-4913-845e-98c4e1ac2ced', 'Number Series', 'Cubes', 'Complete the series: 6, 24, 60, 120, 210, ?', 'Terms are n³ − n for n = 2, 3, …; next n = 7 gives 336.', 'HARD', 1, 0.25, 'PUBLISHED', '2026-11-04 06:09:33.588', '2026-11-04 06:09:33.588', NULL, NULL, NULL, NULL, NULL, NULL, 'MCQ'),
